import{_ as p,a0 as r,w as l,s,ao as d,I as n,x as e,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"使用機器學習來進行卡通上色 | LCTT x X-CMD","titleTemplate":false,"description":"使用機器學習來進行卡通上色 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用機器學習來進行卡通上色 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用機器學習來進行卡通上色 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180425 Using machine learning to color cartoons","title":"使用機器學習來進行卡通上色","tag":"201806","desc":""},"relativePath":"201806/20180425 Using machine learning to color cartoons.md","filePath":"[post].md"}'),m={name:"201806/20180425 Using machine learning to color cartoons.md"};function u(g,t,f,c,h,x){const o=r("Link");return l(),s("div",null,[t[15]||(t[15]=d('<h1 id="使用機器學習來進行卡通上色" tabindex="-1">使用機器學習來進行卡通上色 <a class="header-anchor" href="#使用機器學習來進行卡通上色" aria-label="Permalink to “使用機器學習來進行卡通上色”">​</a></h1><blockquote><p>我們可以自動應用簡單的配色方案，而無需手繪幾百個訓練數據示例嗎？</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/art-yearbook-paint-draw-create-creative.png?itok=t9fOdlyJ" alt=""></p><p>監督式機器學習的一個大問題是需要大量的歸類數據，特別是如果你沒有這些數據時——即使這是一個充斥着大數據的世界，我們大多數人依然沒有大數據——這就真的是一個大問題了。</p><p>儘管少數公司可以訪問某些類型的大量歸類數據，但對於大多數的組織和應用來説，創造足夠的正確類型的歸類數據，花費還是太高了，以至於近乎不可能。在某些時候，這個領域還是一個沒有太多數據的領域（比如説，當我們診斷一種稀有的疾病，或者判斷一個數據是否匹配我們已知的那一點點樣本時）。其他時候，通過 Amazon Turkers 或者暑假工這些人工方式來給我們需要的數據做分類，這樣做的花費太高了。對於一部電影長度的視頻，因為要對每一幀做分類，所以成本上漲得很快，即使是一幀一美分。</p><h3 id="大數據需求的一個大問題" tabindex="-1">大數據需求的一個大問題 <a class="header-anchor" href="#大數據需求的一個大問題" aria-label="Permalink to “大數據需求的一個大問題”">​</a></h3><p>我們團隊目前打算解決一個問題是：我們能不能在沒有手繪的數百或者數千訓練數據的情況下，訓練出一個模型，來自動化地為黑白像素圖片提供簡單的配色方案。</p><p>在這個實驗中（我們稱這個實驗為龍畫），面對深度學習龐大的對分類數據的需求，我們使用以下這種方法：</p><ul><li>對小數據集的快速增長使用基於規則的的策略。</li><li>借用 tensorflow 圖像轉換的模型，Pix2Pix 框架，從而在訓練數據非常有限的情況下實現自動化卡通渲染。</li></ul><p>我曾見過 Pix2Pix 框架，在一篇論文（由 Isola 等人撰寫的“Image-to-Image Translation with Conditional Adversarial Networks”）中描述的機器學習圖像轉換模型，假設 A 是風景圖 B 的灰度版，在對 AB 對進行訓練後，再給風景圖片進行上色。我的問題和這是類似的，唯一的問題就是訓練數據。</p><p>我需要的訓練數據非常有限，因為我不想為了訓練這個模型，一輩子畫畫和上色來為它提供彩色圖片，深度學習模型需要成千上萬（或者成百上千）的訓練數據。</p><p>基於 Pix2Pix 的案例，我們需要至少 400 到 1000 個黑白、彩色成對的數據。你問我願意畫多少？可能就只有 30 個。我畫了一小部分卡通花和卡通龍，然後去確認我是否可以把他們放進數據集中。</p><h3 id="_80-的解決方案-按組件上色" tabindex="-1">80% 的解決方案：按組件上色 <a class="header-anchor" href="#_80-的解決方案-按組件上色" aria-label="Permalink to “80% 的解決方案：按組件上色”">​</a></h3><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/dragonpaint2.png?itok=qw_q72A5" alt="Characters colored by component rules" title="Characters colored by component rules"></p><p><em>按組件規則對黑白像素進行上色</em></p><p>當面對訓練數據的短缺時，要問的第一個問題就是，是否有一個好的非機器學習的方法來解決我們的問題，如果沒有一個完整的解決方案，那是否有一個部分的解決方案，這個部分解決方案對我們是否有好處？我們真的需要機器學習的方法來為花和龍上色嗎？或者我們能為上色指定幾何規則嗎？</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/dragonpaint3.png?itok=JK3TPcvp" alt="How to color by components" title="How to color by components"></p><p><em>如何按組件進行上色</em></p><p>現在有一種非機器學習的方法來解決我的問題。我可以告訴一個孩子，我想怎麼給我的畫上色：把花的中心畫成橙色，把花瓣畫成黃色，把龍的身體畫成橙色，把龍的尖刺畫成黃色。</p><p>開始的時候，這似乎沒有什麼幫助，因為我們的電腦不知道什麼是中心，什麼是花瓣，什麼是身體，什麼是尖刺。但事實證明，我們可以依據連接組件來定義花和龍的部分，然後得到一個幾何解決方案為我們 80% 的畫來上色，雖然 80% 還不夠，我們可以使用戰略性違規轉換、參數和機器學習來引導基於部分規則的解決方案達到 100%。</p><p>連接的組件使用的是 Windows 畫圖（或者類似的應用）上的色，例如，當我們對一個二進制黑白圖像上色時，如果你單擊一個白色像素，這個白色像素會在不穿過黑色的情況下變成一種新的顏色。在一個規則相同的卡通龍或者花的素描中，最大的白色組件就是背景，下一個最大的組件就是身體（加上手臂和腿）或者花的中心，其餘的部分就是尖刺和花瓣，除了龍眼睛，它可以通過和背景的距離來做區分。</p><h3 id="使用戰略規則和-pix2pix-來達到-100" tabindex="-1">使用戰略規則和 Pix2Pix 來達到 100% <a class="header-anchor" href="#使用戰略規則和-pix2pix-來達到-100" aria-label="Permalink to “使用戰略規則和 Pix2Pix 來達到 100%”">​</a></h3><p>我的一部分素描不符合規則，一條粗心畫下的線可能會留下一個缺口，一條後肢可能會上成尖刺的顏色，一個小的，居中的雛菊會交換花瓣和中心的上色規則。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/dragonpaint4.png?itok=MOiaVxMS" alt=""></p><p>對於那 20% 我們不能用幾何規則進行上色的部分，我們需要其他的方法來對它進行處理，我們轉向 Pix2Pix 模型，它至少需要 400 到 1000 個素描/彩色對作為數據集（在 Pix2Pix 論文裏的最小的數據集），裏面包括違反規則的例子。</p><p>所以，對於每個違反規則的例子，我們最後都會通過手工的方式進行上色（比如後肢）或者選取一些符合規則的素描 / 彩色對來打破規則。我們在 A 中刪除一些線，或者我們多轉換一些，居中的花朵 A 和 B 使用相同的函數 (f) 來創造新的一對，f(A) 和 f(B)，一個小而居中的花朵，這可以加入到數據集。</p><h3 id="使用高斯濾波器和同胚增大到最大" tabindex="-1">使用高斯濾波器和同胚增大到最大 <a class="header-anchor" href="#使用高斯濾波器和同胚增大到最大" aria-label="Permalink to “使用高斯濾波器和同胚增大到最大”">​</a></h3><p>在計算機視覺中使用幾何轉換增強數據集是很常見的做法。例如循環，平移，和縮放。</p><p>但是如果我們需要把向日葵轉換為雛菊或者把龍的鼻子變成球型和尖刺型呢？</p><p>或者如果説我們只需要大量增加數據量而不管過擬合？那我們需要比我們一開始使用的數據集大 10 到 30 倍的數據集。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/dragonpaint5.png?itok=GvipU8l8" alt="Sunflower turned into a daisy with r -&gt; r cubed" title="Sunflower turned into a daisy with r -&gt; r cubed"></p><p><em>向日葵通過 r -&gt; r 立方體方式變成一個雛菊</em></p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/dragonpaint6.png?itok=r14I2Fyz" alt="Gaussian filter augmentations" title="Gaussian filter augmentations"></p><p><em>高斯濾波器增強</em></p><p>單位盤的某些同胚可以形成很好的雛菊（比如 r -&gt; r 立方體，高斯濾波器可以改變龍的鼻子。這兩者對於數據集的快速增長是非常有用的，並且產生的大量數據都是我們需要的。但是他們也會開始用一種不能仿射轉換的方式來改變畫的風格。</p><p>之前我們考慮的是如何自動化地設計一個簡單的上色方案，上述內容激發了一個在這之外的問題：什麼東西定義了藝術家的風格，不管是外部的觀察者還是藝術家自己？他們什麼時候確定了自己的的繪畫風格呢？他們不可能沒有自己畫畫的算法？工具、助手和合作者之間的區別是什麼？</p><h3 id="我們可以走多遠" tabindex="-1">我們可以走多遠？ <a class="header-anchor" href="#我們可以走多遠" aria-label="Permalink to “我們可以走多遠？”">​</a></h3><p>我們畫畫的投入可以有多低？保持在一個主題之內並且風格可以辨認出為某個藝術家的作品，在這個範圍內我們可以創造出多少的變化和複雜性？我們需要做什麼才能完成一個有無限的長頸鹿、龍、花的遊行畫卷？如果我們有了這樣一幅，我們可以用它來做什麼？</p><p>這些都是我們會繼續在後面的工作中進行探索的問題。</p><p>但是現在，規則、增強和 Pix2Pix 模型起作用了。我們可以很好地為花上色了，給龍上色也不錯。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/dragonpaint7.png?itok=xKWvyi_T" alt="Results: flowers colored by model trained on flowers" title="Results: flowers colored by model trained on flowers"></p><p><em>結果：通過花這方面的模型訓練來給花上色。</em></p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/dragonpaint8.png?itok=fSM5ovBT" alt="Results: dragons trained on model trained on dragons" title="Results: dragons trained on model trained on dragons"></p><p><em>結果：龍的模型訓練的訓練結果。</em></p><p>想了解更多，參與 Gretchen Greene&#39;s talk, DragonPaint – bootstrapping small data to color cartoons, 在 PyCon Cleveland 2018.</p><hr>',46)),n("p",null,[t[1]||(t[1]=e("via: ",-1)),a(o,{href:"https://opensource.com/article/18/4/dragonpaint-bootstrapping"},{default:i(()=>[...t[0]||(t[0]=[e("https://opensource.com/article/18/4/dragonpaint-bootstrapping",-1)])]),_:1})]),n("p",null,[t[6]||(t[6]=e("作者：",-1)),a(o,{href:"https://opensource.com/users/kggreene"},{default:i(()=>[...t[2]||(t[2]=[e("K. Gretchen Greene",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),a(o,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[3]||(t[3]=[e("lujun9972",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),a(o,{href:"https://github.com/hopefully2333"},{default:i(()=>[...t[4]||(t[4]=[e("hopefully2333",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),a(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=e("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),a(o,{href:"https://linux.cn/"},{default:i(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const T=p(m,[["render",u]]);export{P as __pageData,T as default};
